-- story_highlights (05.2-01) — HIGHLIGHT-01/02/05: named highlights that belong to one PLACE (Início
-- or one community), and the copy of every existing pin into one of them.
--
-- THE FILE IS TWO HALVES, the `20260924022607_story_community_pins.sql` shape:
--
--   1. GENERATED by `drizzle-kit generate --name=story_highlights` from
--      `packages/modules/stories/db/schema.ts` — everything down to the
--      `story_highlights_tenant_isolation` policy, byte for byte. `pnpm db:generate` is a no-op
--      against it, which is the property that keeps the TS schema and this folder honest. The
--      generate is CREATE-ONLY on purpose: `story_community_pins` is still in the schema, because a
--      single generate that both creates and drops tables prompts "created or renamed?" and orders
--      the DROP before anything could copy the pins (05.2 RESEARCH Pattern 2, Pitfall 1). Plan 11's
--      own drop-only file retires the pins table after this one has copied it.
--
--   2. HAND-WRITTEN — three statements:
--
--      a. `story_highlights_community_fk`. It is not generated because it CANNOT be: the
--         communities table belongs to `@rede-social/module-communities`, and `turbo.json`'s boundary
--         allowlist denies a `module -> module` package dependency (MOD-02). The DATABASE enforces
--         it either way, and `120-story-highlights.sql` asserts it (23503 + positive control).
--         `community_id` NULL means Início, and a NULL passes a foreign key by definition.
--
--      b. THE BACKFILL: ONE data-modifying CTE that creates one highlight titled `Destaques` at
--         position 0 per (tenant, community) that HAS pins, and copies every pin into an item of
--         the highlight created for ITS OWN (tenant, community) pair — `added_by_user_id` =
--         `pinned_by_user_id`, `added_at` = `pinned_at`. A story pinned to two communities
--         therefore becomes two items under two highlights, never one merged row. A tenant or
--         community with zero pins gets no highlight at all (the CTE groups over existing pins
--         only), so a fresh `db reset` — where the seed runs AFTER migrations — migrates zero rows.
--
--      c. THE GUARD: a `DO` block that RAISES when any pin has no matching item, or any
--         community's item count differs from its pin count. The Supabase CLI applies one
--         migration file atomically (verified on CLI 2.117: a probe that raised left neither its
--         table nor a `schema_migrations` row), so a tripped guard aborts the WHOLE file — the
--         tables included — rather than let an environment lose a pin.
--
-- WHY THE BACKFILL AND ITS GUARD LIVE IN THIS FILE and not in a `--custom` one: the copy is only
-- meaningful in the same transaction as the tables it fills. Split into a second file, a failed
-- copy would leave empty highlight tables committed beside the pins, and the drop that plan 11
-- ships could then run against a database whose copy never happened.
--
-- WHY THE COVER STAYS NULL IN THE BACKFILL: the cover is resolved at READ time (R-D-D). With no
-- chosen cover, the rule falls to "the most recently ADDED live image item", and for a migrated
-- highlight `added_at = pinned_at` — so the read already yields the most recently pinned story as
-- the cover (D-116) without this file choosing one.
--
-- WHY PLAY ORDER IS NOT A BACKFILL CONCERN: items carry no ordering column (D-103). A highlight
-- plays by the STORY's `published_at`, so two pins with equal `pinned_at` cannot change the order.
--
-- WHY THE FOREIGN KEY IS VALIDATING AND NOT `NOT VALID`: the table is created in this same file and
-- holds only the rows the backfill wrote from pins whose community FK was already enforced.
--
-- ── GENERATED (half 1) ─────────────────────────────────────────────────────────────────────────
CREATE TABLE "story_highlight_items" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"highlight_id" uuid NOT NULL,
	"story_id" uuid NOT NULL,
	"added_by_user_id" uuid NOT NULL,
	"added_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
ALTER TABLE "story_highlight_items" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE TABLE "story_highlights" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"community_id" uuid,
	"title" text NOT NULL,
	"position" integer NOT NULL,
	"cover_story_id" uuid,
	"cover_asset_id" uuid,
	"created_by_user_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "story_highlights_title_chk" CHECK (char_length("story_highlights"."title") between 1 and 15 and "story_highlights"."title" = btrim("story_highlights"."title")),
	CONSTRAINT "story_highlights_cover_chk" CHECK (num_nonnulls("story_highlights"."cover_story_id", "story_highlights"."cover_asset_id") <= 1),
	CONSTRAINT "story_highlights_position_chk" CHECK ("story_highlights"."position" >= 0)
);
