CREATE POLICY "story_highlight_items_tenant_isolation" ON "story_highlight_items" AS PERMISSIVE FOR ALL TO "authenticated" USING (tenant_id = app.tenant_id()) WITH CHECK (tenant_id = app.tenant_id());--> statement-breakpoint
CREATE POLICY "story_highlights_tenant_isolation" ON "story_highlights" AS PERMISSIVE FOR ALL TO "authenticated" USING (tenant_id = app.tenant_id()) WITH CHECK (tenant_id = app.tenant_id());
--> statement-breakpoint
-- ── HAND-WRITTEN (half 2) ──────────────────────────────────────────────────────────────────────
-- (a) `on delete cascade`: archiving is what the product offers, but if a tenant row ever cascades
-- through a community, a highlight pointing at a container that no longer exists would be a row no
-- read could ever explain. Its items go with it through `story_highlight_items`' own cascade.
ALTER TABLE "story_highlights" ADD CONSTRAINT "story_highlights_community_fk" FOREIGN KEY ("community_id") REFERENCES "public"."communities"("id") ON DELETE cascade;
--> statement-breakpoint
-- (b) THE BACKFILL — ONE data-modifying CTE: every item joins the highlight created for ITS OWN
-- (tenant, community) pair, never a title match. `first_pinner` is the curator of the first pin, and
-- the highlight's `created_at` / `updated_at` span the first and last pin of its community.
with pinned as (
  select p.tenant_id, p.community_id,
         min(p.pinned_at) as first_pinned_at,
         max(p.pinned_at) as last_pinned_at,
         (array_agg(p.pinned_by_user_id order by p.pinned_at, p.id))[1] as first_pinner
    from public.story_community_pins p
   group by p.tenant_id, p.community_id
), created as (
  insert into public.story_highlights
    (tenant_id, community_id, title, position, created_by_user_id, created_at, updated_at)
  select tenant_id, community_id, 'Destaques', 0, first_pinner, first_pinned_at, last_pinned_at
    from pinned
  returning id, tenant_id, community_id
)
insert into public.story_highlight_items (tenant_id, highlight_id, story_id, added_by_user_id, added_at)
select p.tenant_id, c.id, p.story_id, p.pinned_by_user_id, p.pinned_at
  from public.story_community_pins p
  join created c on c.tenant_id = p.tenant_id and c.community_id = p.community_id;
--> statement-breakpoint
-- (c) THE GUARD: abort the whole file (atomic, verified on CLI 2.117) rather than lose a pin. Two
-- independent checks — a pin with no identical item under its own community's highlight, and a
-- (tenant, community) whose item count differs from its pin count — and the exception names both.
do $$
declare
  v_missing int;
  v_mismatch int;
begin
  select count(*) into v_missing
    from public.story_community_pins p
   where not exists (
     select 1
       from public.story_highlight_items i
       join public.story_highlights h on h.id = i.highlight_id
      where i.story_id = p.story_id
        and h.community_id = p.community_id
        and h.tenant_id = p.tenant_id
        and i.tenant_id = p.tenant_id
        and i.added_at = p.pinned_at
        and i.added_by_user_id = p.pinned_by_user_id);

  select count(*) into v_mismatch
    from (
      select tenant_id, community_id, count(*) as n
        from public.story_community_pins
       group by 1, 2) a
    full join (
      select h.tenant_id, h.community_id, count(*) as n
        from public.story_highlight_items i
        join public.story_highlights h on h.id = i.highlight_id
       group by 1, 2) b using (tenant_id, community_id)
   where a.n is distinct from b.n;

  if v_missing > 0 or v_mismatch > 0 then
    raise exception 'story_highlights backfill would lose pins: % missing, % communities mismatched',
      v_missing, v_mismatch;
  end if;
end $$;
